const body = $input.first().json.body || $input.first().json;

// Enforce boundary isolation: must have input (PharmacyReviewInput)
const input = body.input || body;

if (!input || !input.proposedPrescription || !input.patientId) {
  throw new Error('Invalid request payload: missing required PharmacyReviewInput boundary.');
}

// Ensure raw ClinicalContext is strictly not passed to Qwen
const patientId = input.patientId;
const prescriptionDraft = input.proposedPrescription;
const relevantDiagnoses = input.relevantDiagnoses || [];
const allergies = input.allergies || [];
const currentMedications = input.currentMedications || [];
const relevantObservations = input.relevantObservations || [];
const deterministicFindings = input.deterministicFindings || [];
const unavailableData = input.unavailableData || [];

const systemInstruction = `
Eres el Asistente Farmacéutico de SAMED (Sistema de Apoyo Médico para Evaluación y Decisión).
Tu rol es EXCLUSIVAMENTE CONSULTIVO Y DE REVISIÓN FARMACOTERAPÉUTICA para un prototipo con datos sintéticos.

INVARIANTES CRÍTICOS:
1. Los hallazgos determinísticos (deterministicFindings) son hallazgos determinísticos autoritativos dentro del prototipo SAMED. NUNCA los contradigas, descartes ni alteres.
2. La revisión que generas apoya la decisión del profesional; el médico retiene la AUTORIDAD DECISORIA FINAL.
3. NO autorizas ni emites recetas médicas.
4. Realizas una evaluación farmacológica independiente basada strictly en la medicación activa, alergias y pauta propuesta.
5. EVALUACIÓN DE ESTADO (status):
   - 'BLOCKED_BY_MISSING_DATA': Si faltan datos críticos para evaluar la seguridad (ej. creatinina/eGFR en fármacos de eliminación renal, potasio en diuréticos/IECA, etc.). DATO FALTANTE ≠ NORMAL.
   - 'REVIEW_RECOMMENDED': Si hay hallazgos determinísticos activos de riesgo crítico o advertencia que requieren ajuste de dosis o consideración de alternativas.
   - 'NO_ADDITIONAL_CONCERNS': Si no se identifican contraindicaciones adicionales ni datos faltantes bloqueantes en el alcance analizado.
6. Genera tu salida ÚNICAMENTE en formato JSON conforme al esquema estricto especificado.
`;

const userPrompt = `
Por favor realiza la revisión farmacoterapéutica de la propuesta de prescripción para el paciente ${patientId}.

PROPUESTA DE PRESCRIPCIÓN:
ID: ${prescriptionDraft.id}
Ítems propuestos:
${JSON.stringify(prescriptionDraft.items || [], null, 2)}
Notas médicas:
${prescriptionDraft.notes || 'Sin notas'}

PERFIL FARMACOLÓGICO ACTIVO:
Diagnósticos relevantes: ${JSON.stringify(relevantDiagnoses)}
Alergias documentadas: ${JSON.stringify(allergies)}
Medicamentos en curso: ${JSON.stringify(currentMedications)}
Observaciones de monitoreo: ${JSON.stringify(relevantObservations)}

HALLAZGOS DETERMINÍSTICOS (Evidencia obligatoria):
${JSON.stringify(deterministicFindings, null, 2)}

DATOS ANALÍTICOS NO DISPONIBLES:
${JSON.stringify(unavailableData, null, 2)}

Genera la revisión en JSON con:
- id: identificador único con prefijo 'pr-review-'
- patientId: '${patientId}'
- prescriptionDraftId: '${prescriptionDraft.id}'
- status: 'NO_ADDITIONAL_CONCERNS' | 'REVIEW_RECOMMENDED' | 'BLOCKED_BY_MISSING_DATA'
- summary: síntesis narrativa de la revisión farmacológica
- pharmacologicalConsiderations: arreglo de cadenas con observaciones farmacológicas
- requiredDataGaps: arreglo de objetos { key: string, status: string, reason?: string }
- deterministicFindingsReferenced: arreglo de cadenas con los IDs de los hallazgos determinísticos
- reviewedAt: marca temporal ISO 8601 actual
- role: 'pharmacy_assistant'
`;

return [{
  json: {
    patientId,
    prescriptionDraftId: prescriptionDraft.id,
    systemInstruction,
    userPrompt,
    deterministicFindings,
    unavailableData
  }
}];

const item = $input.first().json;
const prepData = $('Validate & Prepare Prompt').first().json;

if (item.error) {
  return [{
    json: {
      error: true,
      code: 'GROQ_API_ERROR',
      message: `Groq API Error: ${typeof item.error === 'object' ? JSON.stringify(item.error) : String(item.error)}`
    }
  }];
}

let parsed = null;

try {
  const rawContent = item.choices?.[0]?.message?.content;
  if (rawContent) {
    parsed = typeof rawContent === 'string' ? JSON.parse(rawContent) : rawContent;
  } else if (item.status && item.summary) {
    parsed = item;
  } else {
    throw new Error('Groq API response did not contain valid message content or summary.');
  }
} catch (err) {
  return [{
    json: {
      error: true,
      code: 'MALFORMED_PROVIDER_OUTPUT',
      message: `Failed to parse Qwen provider response: ${err.message}`
    }
  }];
}

const validStatuses = ['NO_ADDITIONAL_CONCERNS', 'REVIEW_RECOMMENDED', 'BLOCKED_BY_MISSING_DATA'];
if (!parsed || typeof parsed !== 'object' || !parsed.summary || typeof parsed.summary !== 'string' || !validStatuses.includes(parsed.status)) {
  return [{
    json: {
      error: true,
      code: 'INVALID_PHARMACY_REVIEW_STRUCTURE',
      message: 'Qwen provider output missing required summary string or valid status enum.'
    }
  }];
}

const normalized = {
  id: String(parsed.id || `pr-review-${prepData.patientId}-${Date.now()}`),
  patientId: String(parsed.patientId || prepData.patientId),
  prescriptionDraftId: String(parsed.prescriptionDraftId || prepData.prescriptionDraftId),
  status: parsed.status,
  summary: String(parsed.summary),
  pharmacologicalConsiderations: Array.isArray(parsed.pharmacologicalConsiderations)
    ? parsed.pharmacologicalConsiderations.map(String)
    : [],
  requiredDataGaps: Array.isArray(parsed.requiredDataGaps)
    ? parsed.requiredDataGaps.map(g => ({
        key: String(g.key || 'unknown_parameter'),
        status: ['AVAILABLE', 'MISSING', 'STALE', 'UNAVAILABLE', 'UNKNOWN'].includes(g.status) ? g.status : 'MISSING',
        reason: g.reason ? String(g.reason) : undefined
      }))
    : [],
  deterministicFindingsReferenced: Array.isArray(parsed.deterministicFindingsReferenced)
    ? parsed.deterministicFindingsReferenced.map(String)
    : (prepData.deterministicFindings || []).map(f => f.id),
  reviewedAt: String(parsed.reviewedAt || new Date().toISOString()),
  role: 'pharmacy_assistant'
};

return [{ json: normalized }];
